<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { api,errorText } from '../api'
import { useLoad,time,shortId } from '../composables'
import type { IncidentDetail,IncidentEvent,Page } from '../types'
import StatusBadge from '../components/StatusBadge.vue'
import PageState from '../components/PageState.vue'
import PaginationBar from '../components/PaginationBar.vue'
import AppIcon from '../components/AppIcon.vue'
import AgentRunsPanel from '../components/AgentRunsPanel.vue'
const route=useRoute(),id=String(route.params.id),eventPage=ref(0)
const {data,loading,error,load}=useLoad(async()=>({detail:await api<IncidentDetail>('/incidents/'+id),events:await api<Page<IncidentEvent>>(`/incidents/${id}/events?page=${eventPage.value}&size=20`)}))
const action=ref<{name:string;label:string;version:number}|null>(null),reason=ref(''),busy=ref(false),saveError=ref('')
const actions=computed(()=>{const i=data.value?.detail.incident;if(!i||!data.value?.detail.canOperate)return[];return i.status==='OPEN'?[{name:'ACK',label:'确认事故'}]:i.status==='ACKNOWLEDGED'?[{name:'INVESTIGATE',label:'开始排查'}]:['INVESTIGATING','MONITORING'].includes(i.status)&&i.recoveredAt?[{name:'RESOLVE',label:'确认解决'}]:i.status==='RESOLVED'?[{name:'CLOSE',label:'关闭事故'}]:[]})
function start(value:{name:string;label:string}){if(!data.value)return;action.value={...value,version:data.value.detail.incident.version};reason.value='';saveError.value=''}
async function submit(){if(!action.value)return;busy.value=true;saveError.value='';try{await api('/incidents/'+id+'/transitions',{method:'POST',body:{action:action.value.name,version:action.value.version,reason:reason.value}});action.value=null;eventPage.value=0;await load()}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
function refresh(){action.value=null;void load()};onMounted(load);const timer=setInterval(load,15000);onUnmounted(()=>clearInterval(timer))
const eventNames:Record<string,string>={AGENT_WAITING_HUMAN:'等待人工审阅',AGENT_REVIEW_DECIDED:'已记录审阅决定',AGENT_REVIEW_SYNCED:'审阅决定已同步',AGENT_REVIEW_EXPIRED:'审阅过期，任务取消',AGENT_MANUAL_REPORTED:'已回填线下处理',AGENT_RUN_REQUESTED:'已发起只读诊断',AGENT_RUN_COMPLETED:'只读诊断已完成',INCIDENT_OPENED:'发现服务故障',INCIDENT_ACKNOWLEDGED:'已确认事故',INCIDENT_INVESTIGATING:'开始排查',INCIDENT_MONITORING:'进入恢复观察',INCIDENT_RESOLVED:'事故已解决',INCIDENT_CLOSED:'事故已关闭',CHECK_FAILED:'检查仍然异常',CHECK_UNKNOWN:'检查结果未知',RECOVERY_DETECTED:'检查恢复达到阈值',RECOVERY_INTERRUPTED:'恢复观察被中断',CHECK_SUSPENDED:'检查已暂停或禁用'}
</script>
<template><RouterLink to="/incidents" class="back-link"><AppIcon name="arrow" :size="16" />事故队列</RouterLink><PageState :loading="loading&&!data" :error="error" @retry="load"><template v-if="data"><div class="page-heading"><div><div class="title-line"><h1>{{ data.detail.incident.targetName }}</h1><StatusBadge :value="data.detail.incident.status" /></div><p>{{ data.detail.incident.summary }}</p></div><div class="actions"><button class="btn" :disabled="loading" @click="refresh"><AppIcon name="refresh" :size="16" />刷新时间线</button><button v-for="a in actions" :key="a.name" class="btn primary" @click="start(a)">{{ a.label }}</button></div></div><div class="incident-facts"><div><span>事故编号</span><code :title="id">{{ shortId(id) }}</code></div><div><span>等级</span><strong>{{ data.detail.incident.severity }}</strong></div><div><span>首次发现</span><strong>{{ time(data.detail.incident.openedAt) }}</strong></div><div><span>最近失败</span><strong>{{ time(data.detail.incident.lastFailureAt) }}</strong></div><div><span>当前版本</span><strong class="mono">v{{ data.detail.incident.version }}</strong></div></div><AgentRunsPanel :incident-id="id" :can-operate="data.detail.canOperate" /><div class="incident-columns"><section class="panel"><div class="panel-heading"><h2>事件时间线 <span class="heading-count">{{ data.events.total }}</span></h2><span class="muted">最近事件优先</span></div><form v-if="action" class="inline-form" @submit.prevent="submit"><h3>{{ action.label }}</h3><p class="muted">基于事故版本 {{ action.version }} 提交，处理理由会记录在时间线与审计中。</p><div v-if="saveError" class="error-message" role="alert">{{ saveError }}<button type="button" class="text-button" @click="refresh">刷新后重试</button></div><label>处理理由<textarea v-model="reason" required maxlength="2000" rows="3" placeholder="说明你的确认、排查进展或处理结论"></textarea></label><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="action=null">取消</button><button class="btn primary" :disabled="busy">{{ busy?'提交中…':action.label }}</button></div></form><PageState :empty="!data.events.items.length" title="还没有时间线事件" description="自动检查与人工处理会持续补充此事故的记录。"><ol class="timeline"><li v-for="e in data.events.items" :key="e.id"><span class="timeline-mark"><AppIcon :name="e.actorId?'users':'pulse'" :size="15" /></span><div class="timeline-content"><div class="timeline-title"><strong>{{ eventNames[e.eventType]||e.eventType }}</strong><time>{{ time(e.createdAt) }}</time></div><small class="muted" :title="e.actorId||undefined">{{ e.actorId?'人工处理':e.eventType.startsWith('AGENT_')?'自动诊断':'自动检查' }}</small><p v-if="e.body" class="preserve-text">{{ e.body }}</p><div class="evidence-links"><RouterLink v-if="typeof e.metadata.runId==='string'" :to="'/agent-runs/'+e.metadata.runId" class="evidence-tag">查看诊断与审阅</RouterLink><span v-if="typeof e.metadata.checkRunId==='string'" class="evidence-tag" :title="e.metadata.checkRunId">检查结果 {{ shortId(e.metadata.checkRunId) }}</span><RouterLink v-if="typeof e.metadata.checkId==='string'" :to="{path:'/targets/'+data.detail.incident.targetId,query:{tab:'history',checkId:e.metadata.checkId}}" class="evidence-tag">查看检查历史</RouterLink><span v-if="e.metadata.version!==undefined" class="evidence-tag">版本 {{ e.metadata.version }}</span></div></div></li></ol><PaginationBar :page="eventPage" :size="20" :total="data.events.total" :loading="loading" @change="p=>{eventPage=p;load()}" /></PageState></section><aside class="panel incident-context"><h2>恢复与处理</h2><p>检查恢复只代表证据满足恢复阈值。事故仍需按确认、排查、观察流程推进。</p><dl><dt>恢复证据</dt><dd>{{ data.detail.incident.recoveredAt?time(data.detail.incident.recoveredAt):'尚未满足恢复条件' }}</dd><dt>解决时间</dt><dd>{{ data.detail.incident.resolvedAt?time(data.detail.incident.resolvedAt):'尚未解决' }}</dd><dt>关闭时间</dt><dd>{{ data.detail.incident.closedAt?time(data.detail.incident.closedAt):'尚未关闭' }}</dd></dl><RouterLink :to="'/targets/'+data.detail.incident.targetId" class="btn full">查看服务目标<AppIcon name="chevron" :size="16" /></RouterLink><div v-if="!data.detail.canOperate" class="notice">处理事故需要值班角色及该目标的操作授权。</div><p class="form-hint">恢复观察期间，所有冻结检查再次满足恢复阈值后自动解决；再次异常或暂停检查会中断观察。</p></aside></div></template></PageState></template>
